  qmInvalidHeading: "இந்த மெனு இணைப்பு சரியில்லை",
  qmEmptyBody: "மெனுவின் QR குறியீட்டில் இருந்து திறந்தால் இந்தப் பக்கம் உணவகத்தின் மெனுவைக் காட்டும். மெனுவின் QR குறியீட்டை ஸ்கேன் செய்யுங்கள், இங்கே தெரியும்.",
  qmOfflineBody: "இந்த QR குறியீடு இணையத்தில் வைத்த மெனுவுக்கு அழைத்துச் செல்கிறது, எனவே இணைய இணைப்பு தேவை. உங்கள் இணைப்பைப் பார்த்து மீண்டும் முயலுங்கள்.",
  qmExpiredBody: "வெளியிட்ட மெனு கடைசியாகத் திறக்கப்பட்ட 180 நாட்களுக்குப் பிறகு நீக்கப்படும். உணவகத்திடம் புதிய QR குறியீடு கேளுங்கள்.",
  qmInvalidBody: "QR குறியீடோ இணைப்போ சிதைந்ததாக அல்லது முழுமையற்றதாகத் தெரிகிறது. QR குறியீட்டை மீண்டும் ஸ்கேன் செய்யுங்கள், அல்லது உணவகத்திடம் புதியது கேளுங்கள்.",
  qmTryAgain: "மீண்டும் முயலுங்கள்",
  qmCreateOwn: "உங்கள் சொந்த மெனு QR உருவாக்குங்கள் — இலவசம்",
  qmPublishOfflineError: "வெளியிட இணைய இணைப்பு தேவை. உங்கள் மெனு அப்படியே உள்ளது.",
  qmPublishFailedError: "சேவையகத்தை அடைய முடியவில்லை. உங்கள் மெனு அப்படியே உள்ளது — மீண்டும் முயலுங்கள்.",
  qmUnpublishConfirm: "இந்த வெளியிட்ட மெனுவை மறந்துவிடவா?\n\nமாற்றுவதற்கான சாவி இந்த உலாவியில் மட்டுமே உள்ளது. நீங்கள் ஏற்கெனவே அச்சிட்ட QR குறியீடுகள் இன்றைய மெனுவைக் காட்டிக்கொண்டே இருக்கும், ஆனால் அவற்றை இனி ஒருபோதும் மாற்ற முடியாது.",
  qmResetConfirm: "மெனு முழுவதையும் நீக்கி புதிதாகத் தொடங்கவா?",
  qmExportFailed: "கோப்பை ஏற்றுமதி செய்ய முடியவில்லை. மீண்டும் முயலுங்கள்.",
  qmImportNoItems: "இந்தக் கோப்பில் மெனுப் பொருள் எதுவும் கிடைக்கவில்லை. தேவையான நிரல்கள்: வகை, உணவின் பெயர், விலை, விளக்கம், வகைமை — உங்கள் தற்போதைய மெனுவை ஒருமுறை ஏற்றுமதி செய்தால் தயாரான மாதிரி கிடைக்கும்.",
  qmImportReplace: "உங்கள் தற்போதைய {current} பொருட்களுக்குப் பதிலாக “{file}” கோப்பின் {imported} பொருட்களை வைக்கவா? உணவகத்தின் விவரம் அப்படியே இருக்கும்.",
