  qmImportExportHint: "உங்கள் மெனுவை Excel-இல் திருத்தி எப்போது வேண்டுமானாலும் மீண்டும் இறக்குமதி செய்யுங்கள். நிரல்கள்: வகை, உணவின் பெயர், விலை, விளக்கம், வகைமை (சைவம்/அசைவம்).",
