  sdShortenFailed: "சுருக்க முடியவில்லை — முழு இணைப்பே பயன்படுகிறது.",
  sdShortened: "சுருங்கிவிட்டது. இந்த நகல் இணையத்தில் வைக்கப்பட்டுள்ளது, கடைசியாகத் திறந்த 180 நாட்களுக்குப் பிறகு நீக்கப்படும் — எனவே திறப்பவருக்கு இணைய இணைப்பு தேவை.",
  sdLongLink: "முழு ஆவணமும் இணைப்பிற்குள்ளேயே இருப்பதால் அது நீளமாக உள்ளது (இணையத்தில் எதுவும் வைக்கப்படவில்லை). கீழே உள்ள QR குறியீடோ WhatsApp பொத்தானோ சிறந்தது — இரண்டும் எந்த நீளத்தையும் சமாளிக்கும்.",
  sdWhatsApp: "WhatsApp",
  sdWhatsAppTo: "{recipient}-க்கு WhatsApp",
  sdRecipientCustomer: "வாடிக்கையாளர்",
  sdDocFrom: "{business} அனுப்பிய {title}",
  sdAmountLine: "தொகை: {amount}",
  sdFootStored: "இணைப்பைச் சுருக்கமாக வைக்க இந்த ஆவணத்தின் ஒரு நகல் சேமிக்கப்பட்டுள்ளது. பெறுபவர் எந்த செயலியோ உள்நுழைவோ இல்லாமல் அதைப் பார்த்து UPI மூலம் செலுத்தலாம்.",
  sdFootInline: "முழு ஆவணமும் இணைப்பிற்குள்ளேயே செல்கிறது — எதுவும் அப்லோடு ஆகாது. பெறுபவர் எந்த செயலியோ உள்நுழைவோ இல்லாமல் அதைப் பார்த்து UPI மூலம் செலுத்தலாம்.",
  svOpeningLink: "இணைப்பு திறக்கிறது…",
  svOneMoment: "ஒரு நிமிடம்.",
  svExpiredTitle: "இந்த இணைப்பின் காலம் முடிந்தது",
  svExpiredBody: "சுருக்கிய இணைப்புகள் கடைசியாகத் திறந்த 180 நாட்கள் வரை வைக்கப்படும், பிறகு நீக்கப்படும். அனுப்பியவரிடம் மீண்டும் அனுப்பச் சொல்லுங்கள்.",
  svFailedTitle: "இந்த இணைப்பைத் திறக்க முடியவில்லை",
  svFailedBody: "இந்த இணைப்புக்கு இணைய இணைப்பு தேவை, ஏனெனில் ஆவணம் இணைப்பிற்குள் இல்லாமல் தனியே வைக்கப்பட்டுள்ளது. உங்கள் இணைப்பைப் பார்த்து மீண்டும் முயலுங்கள்.",
  svBrokenTitle: "இந்த இணைப்பு காலியானதோ சிதைந்ததோ",
  svBrokenBody: "ஆவணத்தின் தகவல் இணைப்பிற்குள்ளேயே இருக்கும். அனுப்பியவரிடம் மீண்டும் அனுப்பச் சொல்லுங்கள் — முழு இணைப்பு துண்டிக்கப்பட்டிருக்கலாம்.",
  svSharedWith: "{link}-யின் இலவச கருவி மூலம் பகிரப்பட்டது.",
  svFootShortened: "இது சுருக்கிய இணைப்பு, எனவே ஆவணம் கடைசியாகத் திறந்த 180 நாட்கள் வரை வைக்கப்படும்.",
  svFootInline: "உங்கள் தகவல் இணைப்பிலேயே இருக்கும் — எந்தச் சேவையகத்திலும் எதுவும் வைக்கப்படுவதில்லை.",
  svRxDisclaimer: "இது உங்கள் மருத்துவர் தந்த மருந்துச் சீட்டின் நகல். மருந்துகளைச் சொன்னபடி மட்டுமே எடுத்துக் கொள்ளுங்கள், ஏதும் புரியவில்லை என்றால் மருந்தகத்தைக் கேளுங்கள்.",
