  qmPublishBody2: "ప్రచురిస్తే మెనూ మా దగ్గర ఉంటుంది, QRలో దాని స్థానంలో ఒక చిన్న లింక్ వస్తుంది. ముద్రించిన కోడ్ ఇకపై ఎప్పుడూ మారదు, పరిమాణం పరిమితి పోతుంది. అప్పుడు చూడటానికి కస్టమర్లకు ఇంటర్నెట్ కావాలి, చివరిగా స్కాన్ చేసిన 180 రోజుల తర్వాత మెనూను తొలగిస్తాం.",
