  qmOnlyThisBrowserBody: "ఇది మీదే అని నిరూపించే తాళం ఇక్కడే ఉంది, మరెక్కడా లేదు. దాన్ని తిరిగి పొందడానికి ఏ లాగిన్ లేదు, కాబట్టి ఈ బ్రౌజర్ డేటా తుడిచేయడం — లేదా వేరే ఫోన్ లేదా కంప్యూటర్‌కు మారడం — అంటే ముద్రించిన QRను ఇకపై ఎప్పుడూ మార్చలేరు. మెనూలోని విషయాల ఒక నకలు ఉంచుకోవడానికి పేజీ పైనుంచి దాన్ని ఎగుమతి చేసుకోండి.",
