  qmPublishBody2: "प्रकाशित केल्यावर मेनू आमच्याकडे ठेवला जातो आणि QR मध्ये त्याच्या जागी एक छोटा दुवा येतो. छापलेला कोड पुन्हा कधीही बदलत नाही, आणि आकाराची मर्यादा संपते. तेव्हा ग्राहकांना पाहण्यासाठी इंटरनेट लागते, आणि शेवटच्या स्कॅननंतर 180 दिवसांनी आम्ही मेनू काढून टाकतो.",
  qmPublishing: "प्रकाशित होत आहे…",
  qmPublishMenu: "मेनू प्रकाशित करा",
  qmUnpublishedChanges: "तुमचे काही बदल ग्राहकांना अजून दिसत नाहीत.",
