  qmUpdatePublished: "प्रकाशित मेनू अद्ययावत करा",
  qmCopyShortLink: "छोटा दुवा कॉपी करा",
  qmShowSelfContained: "त्याऐवजी स्वयंपूर्ण QR दाखवा — इंटरनेटशिवाय चालतो, पण आकाराची मर्यादा आहे आणि प्रत्येक बदलानंतर पुन्हा छापावा लागतो.",
  qmOnlyThisBrowserTitle: "हा मेनू फक्त याच ब्राउझरमधून बदलता येतो.",
  qmOnlyThisBrowserBody: "हा तुमचा आहे हे सिद्ध करणारी किल्ली येथेच ठेवली आहे, दुसरीकडे कुठेही नाही. ती परत मिळवण्यासाठी कोणतेही लॉगिन नाही, म्हणून या ब्राउझरचा डेटा पुसणे — किंवा दुसऱ्या फोनवर किंवा संगणकावर जाणे — याचा अर्थ छापलेला QR पुन्हा कधीही बदलता येणार नाही. मेनूची एक प्रत ठेवण्यासाठी पानाच्या वरून तो निर्यात करा.",
