  qmTooLargeTitle: "ಒಂದು QR ಕೋಡ್‌ಗೆ ಮೆನು ತುಂಬಾ ದೊಡ್ಡದು.",
  qmTooLargeBody: "ತಿನಿಸುಗಳ ವಿವರ ಚಿಕ್ಕದು ಮಾಡಿ ಅಥವಾ ಕೆಲವು ವಸ್ತುಗಳನ್ನು ತೆಗೆಯಿರಿ — ಅಥವಾ ಮೆನುವನ್ನು ಎರಡು QR ಕೋಡ್‌ಗಳಾಗಿ ಹಂಚಿ (ಉದಾ. ಊಟ ಮತ್ತು ಪಾನೀಯ).",
  qmRemoveLimitTitle: "ಅಥವಾ ಈ ಮಿತಿಯನ್ನು ಪೂರ್ತಿ ತೆಗೆಯಿರಿ",
  qmRemoveLimitBody: "ಪ್ರೀಮಿಯಂ ಸಾಧನದಲ್ಲಿ ನಿಮ್ಮ ಮೆನು ಅಂತರ್ಜಾಲದಲ್ಲಿ ಇರುತ್ತದೆ ಮತ್ತು QR ಕೋಡಿನಲ್ಲಿ ಒಂದು ಸಣ್ಣ ಶಾಶ್ವತ ಕೊಂಡಿ ಮಾತ್ರ ಇರುತ್ತದೆ — ಹಾಗಾಗಿ ಗಾತ್ರದ ಮಿತಿ ಇಲ್ಲ, ಬೆಲೆ ಅಥವಾ ತಿನಿಸು ಬದಲಿಸಿದರೂ ಮುದ್ರಿಸಿದ ಕೋಡ್ ಕೆಲಸ ಮಾಡುತ್ತಲೇ ಇರುತ್ತದೆ.",
