  qmPublishedMenu: "ಪ್ರಕಟಿಸಿದ ಮೆನು",
  qmPublishForPermanent: "ಶಾಶ್ವತ QR ಗಾಗಿ ಪ್ರಕಟಿಸಿ",
  qmPublishBody1: "ಈಗ ಮೆನು ಪೂರ್ತಿ QR ಕೋಡ್ ಒಳಗೇ ಇದೆ, ಹಾಗಾಗಿ ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆಯೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ಆದರೆ ಬೆಲೆ ಬದಲಿಸಿದಾಗೆಲ್ಲ ಕೋಡ್ ಮತ್ತೆ ಮುದ್ರಿಸಬೇಕು, ಮೆನು ಒಳಗೆ ಹಿಡಿಸುವಷ್ಟು ಚಿಕ್ಕದಾಗಿ ಇರಬೇಕು.",
  qmPublishBody2: "ಪ್ರಕಟಿಸಿದರೆ ಮೆನು ನಮ್ಮಲ್ಲಿ ಉಳಿಯುತ್ತದೆ ಮತ್ತು QR ನಲ್ಲಿ ಅದರ ಬದಲಿಗೆ ಒಂದು ಸಣ್ಣ ಕೊಂಡಿ ಬರುತ್ತದೆ. ಮುದ್ರಿಸಿದ ಕೋಡ್ ಇನ್ನೆಂದೂ ಬದಲಾಗುವುದಿಲ್ಲ, ಗಾತ್ರದ ಮಿತಿಯೂ ಹೋಗುತ್ತದೆ. ಆಗ ನೋಡಲು ಗ್ರಾಹಕರಿಗೆ ಇಂಟರ್ನೆಟ್ ಬೇಕು, ಮತ್ತು ಕೊನೆಯ ಬಾರಿ ಸ್ಕ್ಯಾನ್ ಆದ 180 ದಿನಗಳ ನಂತರ ನಾವು ಮೆನುವನ್ನು ಅಳಿಸುತ್ತೇವೆ.",
  qmPublishing: "ಪ್ರಕಟಿಸುತ್ತಿದ್ದೇವೆ…",
  qmPublishMenu: "ಮೆನು ಪ್ರಕಟಿಸಿ",
