  qmLiveUpToDate: "ಚಾಲ್ತಿಯಲ್ಲಿದೆ, ತಾಜಾ — ಏನನ್ನೂ ಮತ್ತೆ ಮುದ್ರಿಸಬೇಕಿಲ್ಲ.",
  qmUpdatePublished: "ಪ್ರಕಟಿಸಿದ ಮೆನು ತಾಜಾ ಮಾಡಿ",
  qmCopyShortLink: "ಸಣ್ಣ ಕೊಂಡಿ ನಕಲಿಸಿ",
  qmShowSelfContained: "ಅದರ ಬದಲಿಗೆ ತನ್ನಲ್ಲೇ ಪೂರ್ಣವಾದ QR ತೋರಿಸಿ — ಇಂಟರ್ನೆಟ್ ಇಲ್ಲದೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ, ಆದರೆ ಗಾತ್ರದ ಮಿತಿ ಇದೆ ಮತ್ತು ಪ್ರತಿ ಬದಲಾವಣೆಯ ನಂತರ ಮತ್ತೆ ಮುದ್ರಿಸಬೇಕು.",
  qmOnlyThisBrowserTitle: "ಈ ಮೆನುವನ್ನು ಈ ಬ್ರೌಸರಿನಿಂದಲೇ ಬದಲಿಸಬಹುದು.",
  qmOnlyThisBrowserBody: "ಇದು ನಿಮ್ಮದೇ ಎಂದು ಸಾಬೀತು ಮಾಡುವ ಕೀಲಿ ಇಲ್ಲೇ ಇದೆ, ಬೇರೆಲ್ಲೂ ಇಲ್ಲ. ಅದನ್ನು ಮರಳಿ ಪಡೆಯಲು ಯಾವ ಲಾಗಿನ್ ಇಲ್ಲ, ಹಾಗಾಗಿ ಈ ಬ್ರೌಸರಿನ ಮಾಹಿತಿ ಅಳಿಸುವುದು — ಅಥವಾ ಬೇರೆ ಫೋನ್ ಅಥವಾ ಗಣಕಕ್ಕೆ ಹೋಗುವುದು — ಎಂದರೆ ಮುದ್ರಿಸಿದ QR ಅನ್ನು ಇನ್ನೆಂದೂ ಬದಲಿಸಲು ಆಗುವುದಿಲ್ಲ. ಮೆನುವಿನ ಒಂದು ನಕಲು ಇಟ್ಟುಕೊಳ್ಳಲು ಪುಟದ ಮೇಲಿನಿಂದ ಅದನ್ನು ರಫ್ತು ಮಾಡಿಕೊಳ್ಳಿ.",
  qmStopUsingPublished: "ಪ್ರಕಟಿಸಿದ ಕೊಂಡಿ ಬಳಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ",
