  sdFootInline: "ದಾಖಲೆ ಪೂರ್ತಿ ಕೊಂಡಿಯ ಒಳಗೇ ಹೋಗುತ್ತದೆ — ಏನೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ. ಪಡೆಯುವವರು ಯಾವ ಆ್ಯಪ್ ಅಥವಾ ಲಾಗಿನ್ ಇಲ್ಲದೆಯೇ ಅದನ್ನು ನೋಡಿ UPI ಮೂಲಕ ಪಾವತಿಸಬಹುದು.",
