  qmOfflineBody: "ഈ QR കോഡ് ഓൺലൈനിൽ സൂക്ഷിച്ച മെനുവിലേക്കാണ് കൊണ്ടുപോകുന്നത്, അതിനാൽ ഇന്റർനെറ്റ് വേണം. നിങ്ങളുടെ കണക്ഷൻ നോക്കി വീണ്ടും ശ്രമിക്കുക.",
  qmExpiredBody: "പ്രസിദ്ധീകരിച്ച മെനു അവസാനം തുറന്ന് 180 ദിവസം കഴിഞ്ഞാൽ നീക്കം ചെയ്യും. ഹോട്ടലിൽ നിന്ന് പുതിയ QR കോഡ് ചോദിക്കുക.",
  qmInvalidBody: "QR കോഡോ ലിങ്കോ കേടായതോ പൂർണമല്ലാത്തതോ ആയി തോന്നുന്നു. QR കോഡ് വീണ്ടും സ്കാൻ ചെയ്യുക, അല്ലെങ്കിൽ ഹോട്ടലിൽ നിന്ന് പുതിയത് ചോദിക്കുക.",
