  qmUnpublishConfirm: "ഈ പ്രസിദ്ധീകരിച്ച മെനു മറക്കണോ?\n\nമാറ്റാനുള്ള താക്കോൽ ഈ ബ്രൗസറിൽ മാത്രമാണ് സൂക്ഷിച്ചിരിക്കുന്നത്. നിങ്ങൾ നേരത്തേ അച്ചടിച്ച QR കോഡുകൾ ഇന്നത്തെ മെനു തന്നെ കാണിച്ചുകൊണ്ടിരിക്കും, പക്ഷേ അവ ഇനി ഒരിക്കലും മാറ്റാൻ കഴിയില്ല.",
