  sdShortened: "ചുരുങ്ങി. ഈ പകർപ്പ് ഓൺലൈനിൽ സൂക്ഷിച്ചിട്ടുണ്ട്, അവസാനം തുറന്ന് 180 ദിവസം കഴിഞ്ഞാൽ മായ്ക്കും — അതിനാൽ തുറക്കുന്നവർക്ക് ഇന്റർനെറ്റ് വേണം.",
  sdLongLink: "രേഖ മുഴുവൻ ലിങ്കിനുള്ളിൽ തന്നെ ഉള്ളതിനാൽ അത് നീളമുള്ളതാണ് (ഓൺലൈനിൽ ഒന്നും സൂക്ഷിച്ചിട്ടില്ല). താഴെയുള്ള QR കോഡോ WhatsApp ബട്ടണോ നല്ലത് — രണ്ടും ഏത് നീളവും കൈകാര്യം ചെയ്യും.",
