  sdFootStored: "ലിങ്ക് ചുരുങ്ങി നിൽക്കാൻ ഈ രേഖയുടെ ഒരു പകർപ്പ് സൂക്ഷിച്ചിട്ടുണ്ട്. സ്വീകരിക്കുന്നവർക്ക് ആപ്പോ ലോഗിനോ ഇല്ലാതെ അത് കണ്ട് UPI വഴി അടയ്ക്കാം.",
  sdFootInline: "രേഖ മുഴുവൻ ലിങ്കിനുള്ളിൽ തന്നെ പോകുന്നു — ഒന്നും അപ്‌ലോഡ് ആകുന്നില്ല. സ്വീകരിക്കുന്നവർക്ക് ആപ്പോ ലോഗിനോ ഇല്ലാതെ അത് കണ്ട് UPI വഴി അടയ്ക്കാം.",
