  qmInvalidBody: "QR ਕੋਡ ਜਾਂ ਲਿੰਕ ਟੁੱਟਿਆ ਜਾਂ ਅਧੂਰਾ ਲੱਗਦਾ ਹੈ। QR ਕੋਡ ਮੁੜ ਸਕੈਨ ਕਰੋ, ਜਾਂ ਰੈਸਟੋਰੈਂਟ ਤੋਂ ਨਵਾਂ ਮੰਗੋ।",
  qmTryAgain: "ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ",
  qmCreateOwn: "ਆਪਣਾ ਮੈਨਿਊ QR ਬਣਾਓ — ਮੁਫ਼ਤ",
  qmPublishOfflineError: "ਪ੍ਰਕਾਸ਼ਿਤ ਕਰਨ ਲਈ ਇੰਟਰਨੈੱਟ ਚਾਹੀਦਾ ਹੈ। ਤੁਹਾਡਾ ਮੈਨਿਊ ਜਿਵੇਂ ਸੀ ਉਵੇਂ ਹੀ ਹੈ।",
  qmPublishFailedError: "ਸਰਵਰ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚ ਸਕੇ। ਤੁਹਾਡਾ ਮੈਨਿਊ ਜਿਵੇਂ ਸੀ ਉਵੇਂ ਹੀ ਹੈ — ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  qmUnpublishConfirm: "ਇਸ ਪ੍ਰਕਾਸ਼ਿਤ ਮੈਨਿਊ ਨੂੰ ਭੁਲਾ ਦੇਣਾ?\n\nਬਦਲਣ ਵਾਲੀ ਕੁੰਜੀ ਸਿਰਫ਼ ਇਸੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰੱਖੀ ਹੈ। ਤੁਸੀਂ ਪਹਿਲਾਂ ਛਪਵਾਏ QR ਕੋਡ ਅੱਜ ਦਾ ਮੈਨਿਊ ਦਿਖਾਉਂਦੇ ਰਹਿਣਗੇ, ਪਰ ਉਨ੍ਹਾਂ ਨੂੰ ਮੁੜ ਕਦੇ ਬਦਲ ਨਹੀਂ ਸਕੋਗੇ।",
