  qmRemoveLimitBody: "ਪ੍ਰੀਮੀਅਮ ਟੂਲ ਵਿੱਚ ਤੁਹਾਡਾ ਮੈਨਿਊ ਆਨਲਾਈਨ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ ਤੇ QR ਕੋਡ ਵਿੱਚ ਸਿਰਫ਼ ਇੱਕ ਛੋਟਾ ਪੱਕਾ ਲਿੰਕ ਹੁੰਦਾ ਹੈ — ਸੋ ਆਕਾਰ ਦੀ ਕੋਈ ਹੱਦ ਨਹੀਂ, ਤੇ ਕੀਮਤ ਜਾਂ ਪਕਵਾਨ ਬਦਲਣ 'ਤੇ ਵੀ ਛਪਿਆ ਕੋਡ ਚੱਲਦਾ ਰਹਿੰਦਾ ਹੈ।",
