  sdShortenOffline: "ਛੋਟਾ ਕਰਨ ਲਈ ਇੰਟਰਨੈੱਟ ਚਾਹੀਦਾ ਹੈ। ਹੇਠਲਾ ਪੂਰਾ ਲਿੰਕ ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ ਵੀ ਚੱਲਦਾ ਹੈ — ਉਹੀ ਭੇਜ ਦਿਓ।",
  sdShortenFailed: "ਛੋਟਾ ਨਹੀਂ ਹੋ ਸਕਿਆ — ਪੂਰਾ ਲਿੰਕ ਵਰਤਿਆ ਜਾ ਰਿਹਾ ਹੈ।",
  sdShortened: "ਛੋਟਾ ਹੋ ਗਿਆ। ਇਹ ਨਕਲ ਆਨਲਾਈਨ ਰੱਖੀ ਹੈ ਤੇ ਆਖ਼ਰੀ ਵਾਰ ਖੁੱਲ੍ਹਣ ਦੇ 180 ਦਿਨ ਬਾਅਦ ਮਿਟਾ ਦਿੱਤੀ ਜਾਵੇਗੀ — ਸੋ ਖੋਲ੍ਹਣ ਵਾਲੇ ਨੂੰ ਇੰਟਰਨੈੱਟ ਚਾਹੀਦਾ ਹੈ।",
  sdLongLink: "ਲਿੰਕ ਲੰਮਾ ਹੈ ਕਿਉਂਕਿ ਪੂਰਾ ਕਾਗ਼ਜ਼ ਉਸੇ ਦੇ ਅੰਦਰ ਹੈ (ਆਨਲਾਈਨ ਕੁਝ ਨਹੀਂ ਰੱਖਿਆ)। ਹੇਠਲਾ QR ਕੋਡ ਜਾਂ WhatsApp ਬਟਨ ਵਧੀਆ — ਦੋਵੇਂ ਕਿਸੇ ਵੀ ਲੰਬਾਈ ਨੂੰ ਸੰਭਾਲ ਲੈਂਦੇ ਹਨ।",
