  sdAmountLine: "ਰਕਮ: {amount}",
  sdFootStored: "ਲਿੰਕ ਛੋਟਾ ਰਹੇ, ਇਸ ਲਈ ਇਸ ਕਾਗ਼ਜ਼ ਦੀ ਇੱਕ ਨਕਲ ਰੱਖੀ ਗਈ ਹੈ। ਲੈਣ ਵਾਲਾ ਕਿਸੇ ਐਪ ਜਾਂ ਲਾਗਇਨ ਤੋਂ ਬਿਨਾਂ ਉਹ ਵੇਖ ਕੇ UPI ਨਾਲ ਭੁਗਤਾਨ ਕਰ ਸਕਦਾ ਹੈ।",
  sdFootInline: "ਪੂਰਾ ਕਾਗ਼ਜ਼ ਲਿੰਕ ਦੇ ਅੰਦਰ ਹੀ ਜਾਂਦਾ ਹੈ — ਕੁਝ ਅੱਪਲੋਡ ਨਹੀਂ ਹੁੰਦਾ। ਲੈਣ ਵਾਲਾ ਕਿਸੇ ਐਪ ਜਾਂ ਲਾਗਇਨ ਤੋਂ ਬਿਨਾਂ ਉਹ ਵੇਖ ਕੇ UPI ਨਾਲ ਭੁਗਤਾਨ ਕਰ ਸਕਦਾ ਹੈ।",
