  qmPublishBody1: "القائمة كاملة الآن داخل رمز QR، فهو يعمل بلا إنترنت على الإطلاق — لكن يجب إعادة طباعته كلما غيّرت سعرًا، ويجب أن تبقى القائمة صغيرة بما يكفي لتتسع فيه.",
  qmPublishBody2: "عند النشر نحفظ القائمة عندنا ويحمل رمز QR رابطًا قصيرًا بدلًا منها. لا يتغير الرمز المطبوع بعد ذلك أبدًا، ويزول حد الحجم. وفي المقابل يحتاج الزائر إلى اتصال بالإنترنت لرؤيتها، ونحذف القائمة بعد 180 يومًا من آخر مرة يمسحها أحد.",
  qmPublishing: "جارٍ النشر…",
  qmPublishMenu: "نشر القائمة",
  qmUnpublishedChanges: "لديك تغييرات لا يراها العملاء بعد.",
  qmLiveUpToDate: "منشورة ومحدّثة — لا حاجة لإعادة طباعة أي شيء.",
  qmUpdatePublished: "تحديث القائمة المنشورة",
  qmCopyShortLink: "نسخ الرابط القصير",
  qmShowSelfContained: "اعرض بدلًا منه رمز QR المكتفي بذاته — يعمل بلا إنترنت، لكن حجمه محدود ويجب إعادة طباعته بعد كل تغيير.",
  qmOnlyThisBrowserTitle: "هذا المتصفح وحده يمكنه تحديث هذه القائمة.",
  qmOnlyThisBrowserBody: "المفتاح الذي يثبت أنها قائمتك محفوظ هنا ولا مكان غيره. لا يوجد حساب لاستعادته، فمحو بيانات هذا المتصفح — أو الانتقال إلى هاتف أو حاسوب آخر — يعني أن الرمز المطبوع لن يتغير بعد ذلك أبدًا. صدّر قائمتك من أعلى الصفحة للاحتفاظ بنسخة من محتواها.",
  qmStopUsingPublished: "التوقف عن استخدام الرابط المنشور",
